/* The exact body of the "Verify Or Refuse" Code node in the n8n workflow
 * "Meta Lead Ads - Inbound Receiver" — kept here so the repo holds what the box
 * runs, and so every branch can be tested without a live Meta delivery.
 *
 * WHAT MAKES THIS DIFFERENT FROM THE WHATSAPP CLOUD RECEIVER
 *
 * The Cloud receiver gets the customer's message in the webhook. This one does
 * not get the customer AT ALL. Meta's leadgen webhook carries six identifiers —
 * leadgen_id, page_id, form_id, ad_id, adgroup_id, created_time — and no name,
 * no phone, no email. The fields arrive only from a second call,
 * GET /v<v>/<leadgen_id>, which needs `leads_retrieval` and expires.
 *
 * That two-hop shape is why `lead_event` has phases at all, and it is why this
 * node's job ends at RECEIVED. Nothing here invents a customer.
 *
 * AND THE TENANT COMES FROM page_id, WHICH IS ONLY TRUSTWORTHY AFTER THE HMAC
 *
 * There is no public key in a Meta delivery and there cannot be: the callback
 * URL is registered once with Meta and is identical for every dealership. The
 * only per-dealership fact is page_id — and page_id is public, so on its own it
 * is a string an attacker chose. What makes it safe to route on is that it
 * arrived inside a body whose signature verified, AND that it was registered in
 * lead_ingest_provider_identity. Both, in that order, or neither.
 *
 * The same three rules as the Cloud receiver otherwise: hash the RAW bytes,
 * refuse when unconfigured rather than passing traffic through, and carry the
 * HMAC in full because this sandbox has neither require('crypto') nor WebCrypto.
 */
const K = [
  0x428a2f98, 0x71374491, 0xb5c0fbcf, 0xe9b5dba5, 0x3956c25b, 0x59f111f1, 0x923f82a4, 0xab1c5ed5,
  0xd807aa98, 0x12835b01, 0x243185be, 0x550c7dc3, 0x72be5d74, 0x80deb1fe, 0x9bdc06a7, 0xc19bf174,
  0xe49b69c1, 0xefbe4786, 0x0fc19dc6, 0x240ca1cc, 0x2de92c6f, 0x4a7484aa, 0x5cb0a9dc, 0x76f988da,
  0x983e5152, 0xa831c66d, 0xb00327c8, 0xbf597fc7, 0xc6e00bf3, 0xd5a79147, 0x06ca6351, 0x14292967,
  0x27b70a85, 0x2e1b2138, 0x4d2c6dfc, 0x53380d13, 0x650a7354, 0x766a0abb, 0x81c2c92e, 0x92722c85,
  0xa2bfe8a1, 0xa81a664b, 0xc24b8b70, 0xc76c51a3, 0xd192e819, 0xd6990624, 0xf40e3585, 0x106aa070,
  0x19a4c116, 0x1e376c08, 0x2748774c, 0x34b0bcb5, 0x391c0cb3, 0x4ed8aa4a, 0x5b9cca4f, 0x682e6ff3,
  0x748f82ee, 0x78a5636f, 0x84c87814, 0x8cc70208, 0x90befffa, 0xa4506ceb, 0xbef9a3f7, 0xc67178f2];

function sha256(bytes) {
  const H = [0x6a09e667, 0xbb67ae85, 0x3c6ef372, 0xa54ff53a,
             0x510e527f, 0x9b05688c, 0x1f83d9ab, 0x5be0cd19];
  const l = bytes.length;
  /* (l + 8), not (l + 9): at l % 64 === 55 the 0x80 and the length fit the
     current block exactly. The published RFC 4231 vectors all pass with the
     wrong constant; a differential test against node:crypto is what caught it. */
  const buf = new Uint8Array((((l + 8) >> 6) + 1) << 6);
  buf.set(bytes); buf[l] = 0x80;
  const dv = new DataView(buf.buffer), bits = l * 8;
  dv.setUint32(buf.length - 8, Math.floor(bits / 4294967296));
  dv.setUint32(buf.length - 4, bits >>> 0);
  const w = new Uint32Array(64);
  for (let off = 0; off < buf.length; off += 64) {
    for (let i = 0; i < 16; i++) w[i] = dv.getUint32(off + i * 4);
    for (let i = 16; i < 64; i++) {
      const x = w[i - 15], y = w[i - 2];
      const s0 = ((x >>> 7) | (x << 25)) ^ ((x >>> 18) | (x << 14)) ^ (x >>> 3);
      const s1 = ((y >>> 17) | (y << 15)) ^ ((y >>> 19) | (y << 13)) ^ (y >>> 10);
      w[i] = (w[i - 16] + s0 + w[i - 7] + s1) >>> 0;
    }
    let a = H[0], b = H[1], c = H[2], d = H[3], e = H[4], f = H[5], g = H[6], h = H[7];
    for (let i = 0; i < 64; i++) {
      const S1 = ((e >>> 6) | (e << 26)) ^ ((e >>> 11) | (e << 21)) ^ ((e >>> 25) | (e << 7));
      const t1 = (h + S1 + ((e & f) ^ (~e & g)) + K[i] + w[i]) >>> 0;
      const S0 = ((a >>> 2) | (a << 30)) ^ ((a >>> 13) | (a << 19)) ^ ((a >>> 22) | (a << 10));
      const t2 = (S0 + ((a & b) ^ (a & c) ^ (b & c))) >>> 0;
      h = g; g = f; f = e; e = (d + t1) >>> 0; d = c; c = b; b = a; a = (t1 + t2) >>> 0;
    }
    H[0] = (H[0] + a) >>> 0; H[1] = (H[1] + b) >>> 0; H[2] = (H[2] + c) >>> 0; H[3] = (H[3] + d) >>> 0;
    H[4] = (H[4] + e) >>> 0; H[5] = (H[5] + f) >>> 0; H[6] = (H[6] + g) >>> 0; H[7] = (H[7] + h) >>> 0;
  }
  const out = new Uint8Array(32), odv = new DataView(out.buffer);
  for (let i = 0; i < 8; i++) odv.setUint32(i * 4, H[i]);
  return out;
}

function hmacHex(keyBytes, msgBytes) {
  const k = keyBytes.length > 64 ? sha256(keyBytes) : keyBytes;
  const ipad = new Uint8Array(64), opad = new Uint8Array(64);
  for (let i = 0; i < 64; i++) {
    const kb = i < k.length ? k[i] : 0;
    ipad[i] = kb ^ 0x36; opad[i] = kb ^ 0x5c;
  }
  const inner = new Uint8Array(64 + msgBytes.length);
  inner.set(ipad); inner.set(msgBytes, 64);
  const outer = new Uint8Array(96);
  outer.set(opad); outer.set(sha256(inner), 64);
  return Array.from(sha256(outer)).map(b => b.toString(16).padStart(2, '0')).join('');
}

const item = $input.first();
const j = item.json || {};
const headers = j.headers || {};
const query = j.query || {};
const VERIFY_TOKEN = String($env.META_WEBHOOK_VERIFY_TOKEN || '');
const APP_SECRET = String($env.META_APP_SECRET || '');

const refuse = (status, code, why, extra) => [{ json: Object.assign(
  { verdict: 'REFUSE', respond_status: status, respond_text: code,
    reason_code: code, why, wrote_nothing: true }, extra || {}) }];

const sameString = (a, b) => {
  if (a.length !== b.length) return false;
  let d = 0;
  for (let i = 0; i < a.length; i++) d |= a.charCodeAt(i) ^ b.charCodeAt(i);
  return d === 0;
};

/* ---- Meta's GET subscription handshake ------------------------------------ */
if (query['hub.mode'] !== undefined || query['hub.challenge'] !== undefined) {
  if (!VERIFY_TOKEN) {
    return refuse(500, 'VERIFY_TOKEN_NOT_CONFIGURED',
      'META_WEBHOOK_VERIFY_TOKEN is unset on this box. Confirming a subscription ' +
      'we cannot authenticate would let anyone point Meta deliveries at us.');
  }
  if (String(query['hub.mode']) !== 'subscribe') {
    return refuse(400, 'HUB_MODE_NOT_SUBSCRIBE', 'hub.mode was not subscribe.');
  }
  if (!sameString(String(query['hub.verify_token'] || ''), VERIFY_TOKEN)) {
    return refuse(403, 'HUB_VERIFY_TOKEN_MISMATCH', 'The verify token did not match.');
  }
  return [{ json: {
    verdict: 'CHALLENGE', respond_status: 200,
    respond_text: String(query['hub.challenge'] || ''),
    reason_code: 'SUBSCRIPTION_CONFIRMED', wrote_nothing: true } }];
}

/* ---- Everything below is a POST delivery ---------------------------------- */
if (!APP_SECRET) {
  const V = [
    ['key', Buffer.from('The quick brown fox jumps over the lazy dog', 'utf8'),
     'f7bc83f430538424b13298e6aa6fb143ef4d59a14946175997479dbc2d1a3cd8'],
    ['key', Buffer.alloc(55, 0x61),
     '5c753ac4cf15a28e7b5a045ba8ce75e02545a313f326021d770912f768fb53ef'],
    ['key', Buffer.alloc(119, 0x61),
     '4ffbedd6a1157e63e62d3fa284549bcfe39fb98dbb77ac48a89120aed5747d6b'],
  ];
  let selftest;
  try {
    const failed = V.filter(v => hmacHex(Buffer.from(v[0], 'utf8'), v[1]) !== v[2]).length;
    const negative = hmacHex(Buffer.from('wrong-key', 'utf8'), V[0][1]) !== V[0][2];
    selftest = { vectors: V.length, failed, negative_control_rejects: negative,
                 ok: failed === 0 && negative };
  } catch (e) { selftest = { ok: false, error: String((e && e.message) || e) }; }
  return refuse(500, 'APP_SECRET_NOT_CONFIGURED',
    'META_APP_SECRET is unset on this box, so no delivery can be verified. ' +
    'Refusing every request until it is set - this gate is never dormant.',
    { hmac_selftest: selftest });
}

let raw = null, raw_source = null;
const bin = item.binary && (item.binary.data || item.binary.body);
if (bin && bin.data) { raw = Buffer.from(bin.data, 'base64'); raw_source = 'binary'; }
else if (typeof j.body === 'string') { raw = Buffer.from(j.body, 'utf8'); raw_source = 'string'; }
if (!raw) {
  return refuse(500, 'RAW_BODY_NOT_AVAILABLE',
    'The webhook node did not hand this node the raw body, so the bytes Meta ' +
    'signed are already gone. Turn on Raw Body on the webhook node.');
}

const sigHeader = String(headers['x-hub-signature-256'] || '');
if (!sigHeader.startsWith('sha256=')) {
  return refuse(401, 'SIGNATURE_HEADER_MISSING',
    'No X-Hub-Signature-256 on the request. Meta always sends one.');
}
if (!sameString(sigHeader, 'sha256=' + hmacHex(Buffer.from(APP_SECRET, 'utf8'), raw))) {
  return refuse(401, 'SIGNATURE_MISMATCH',
    'X-Hub-Signature-256 did not match an HMAC-SHA256 of the raw body under the ' +
    'app secret. Nothing was written.');
}

let payload;
try { payload = JSON.parse(raw.toString('utf8')); }
catch (e) { return refuse(400, 'BODY_NOT_JSON', 'Signature verified but the body is not JSON.'); }

/* Meta sends `object: "page"` for leadgen. A `whatsapp_business_account`
   delivery arriving here means the two webhooks are crossed in the Meta app
   config — say that, rather than silently finding no leads in it. */
const obj = String(payload.object || '');
if (obj && obj !== 'page') {
  return refuse(400, 'WRONG_WEBHOOK_OBJECT',
    'Signature verified, but object is "' + obj + '" and this endpoint consumes ' +
    'page leadgen. Check which callback URL each field is subscribed to in the ' +
    'Meta app: a whatsapp_business_account delivery belongs at ' +
    '/webhook/whatsapp-cloud-inbound.');
}

const out = [];
let sawNonLeadgen = 0;
for (const entry of (payload.entry || [])) {
  for (const ch of (entry.changes || [])) {
    if (String(ch.field || '') !== 'leadgen') { sawNonLeadgen++; continue; }
    const v = ch.value || {};
    const leadgenId = String(v.leadgen_id || '');
    const pageId = String(v.page_id || entry.id || '');
    const created = Number(v.created_time || 0);
    /* A leadgen_id is the ONLY thing that can fetch the customer and the only
       stable identity for deduplicating Meta's redeliveries. Without it there is
       nothing to hydrate and nothing to key on. Without a page_id there is no
       dealership. Neither is inventable. */
    const usable = leadgenId !== '' && pageId !== '';
    out.push({ json: {
      verdict: usable ? 'ACCEPT' : 'ACCEPT_UNUSABLE',
      respond_status: 200, respond_text: 'ok',
      reason_code: usable ? 'SIGNATURE_VERIFIED'
                          : (leadgenId === '' ? 'NO_LEADGEN_ID' : 'NO_PAGE_ID'),
      raw_source,
      page_id: pageId,
      leadgen_id: leadgenId,
      form_id: String(v.form_id || ''),
      ad_id: String(v.ad_id || ''),
      adgroup_id: String(v.adgroup_id || ''),
      created_time: created > 0 ? new Date(created * 1000).toISOString() : null,
      origin_verified: 'hmac_sha256_x_hub',
      /* payload_raw for the RECEIVED row. Six identifiers and nothing else,
         because that is genuinely all Meta sent — this is not a redaction, it
         is the shape of the delivery. */
      payload_raw: {
        provider: 'meta',
        object: obj || 'page',
        field: 'leadgen',
        leadgen_id: leadgenId,
        page_id: pageId,
        form_id: String(v.form_id || ''),
        ad_id: String(v.ad_id || ''),
        adgroup_id: String(v.adgroup_id || ''),
        created_time: created || null,
      },
    } });
  }
}

if (!out.length) {
  return [{ json: {
    verdict: 'ACCEPT_NO_LEAD', respond_status: 200, respond_text: 'ok',
    reason_code: sawNonLeadgen ? 'NO_LEADGEN_CHANGE_IN_DELIVERY' : 'EMPTY_DELIVERY',
    wrote_nothing: true, raw_source, other_fields_seen: sawNonLeadgen,
    note: 'Signature verified. This delivery carried no leadgen change - Meta ' +
          'sends other Page fields on the same subscription and they are not ' +
          'leads.' } }];
}
return out;

/* The exact body of the "Fetch Lead From Graph" Code node in the n8n workflow
 * "Meta Lead Ads - Inbound Receiver" — hop two, the one that was never written.
 *
 * WHY THIS NODE HAS TO EXIST AT ALL
 *
 * Hop one (`verify-and-extract.node.js`) proves the delivery came from Meta and
 * pulls six identifiers out of it. None of them is a customer. Hop three
 * (`normalize-and-redact.node.js`) expects `$input.first().json` to already BE
 * the Graph API's answer for that lead. Between those two files there was a gap
 * the repository described in prose and never filled: the single HTTP call that
 * turns a leadgen_id into a person.
 *
 * GET https://graph.facebook.com/v<v>/<leadgen_id>?fields=...
 *
 * FOUR RULES THIS NODE EXISTS TO KEEP
 *
 * 1. THE TOKEN GOES IN A HEADER, NEVER IN THE QUERY STRING.
 *    Graph accepts `?access_token=EAA...`. Every guide uses it. It is also how
 *    a Page token ends up permanently readable in the n8n execution record, in
 *    the reverse proxy's access log, and in whatever sits between this box and
 *    Meta. `Authorization: Bearer` keeps it out of all three. The URL built
 *    below carries only the lead id and the field list, and that is on purpose.
 *
 * 2. THE TOKEN IS PER PAGE, RESOLVED FROM page_id, AND THERE IS NO OTHER.
 *    One n8n box serves many dealerships. Each connects its own Facebook Page
 *    and its Page access token is stored in the vault (NX980) against that
 *    Page's lead-ingest endpoint, kind 'meta_page_access_token'. The token is
 *    fetched per lead, keyed on the page_id that arrived inside the body whose
 *    HMAC verified (the HMAC is the one app-level secret, META_APP_SECRET:
 *    there is one NEXUS Meta app). There is NO box-wide token and no fallback
 *    to one: no box-level Page token env var is read. A fallback nobody turns
 *    off is how a system stays single-tenant forever while looking otherwise.
 *
 * 2b. THE TOKEN'S DEALERSHIP MUST BE THE ROW'S DEALERSHIP.
 *    Record Lead Event wrote the RECEIVED row under a tenant. The vault answers
 *    with the tenant that owns the Page token. If they differ, or either is
 *    missing, nothing is fetched: a Page of tenant X only ever produces leads
 *    for X, and a lead of X is never read with Y's credential.
 *
 * 3. GRAPH'S error.message NEVER LEAVES THIS NODE.
 *    Meta's OAuthException messages routinely echo the request back, and this
 *    request carried a Bearer token. `error.message` is read nowhere below.
 *    Only `error.code`, `error.error_subcode` and `error.type` are carried out,
 *    and the human-readable sentence attached to each is OURS — written here,
 *    from the code, so it says what the dealership must actually go and fix.
 *    (`fbtrace_id` is deliberately not carried either: harmless in isolation,
 *    but the moment it is carried somebody adds `message` beside it.)
 *
 * 4. EVERY PATH FAILS CLOSED, WITH A NAME.
 *    There is no branch that returns a half-lead, and none that invents one.
 *    A failure here leaves the lead_event row exactly where door one put it —
 *    phase RECEIVED, no `leads` row, nothing a salesperson can see — and says
 *    which of the six named things went wrong. That is the whole point of the
 *    phases: a broken token produces a row that stops, not a blank customer.
 *
 * ON THE HTTP STATUS THIS NODE ASKS THE WORKFLOW TO ANSWER META.
 *    `respond_status` is 500 when a retry of the SAME delivery could still
 *    succeed once a human fixes something (no token, wrong token, no Lead
 *    Access, rate limit, Graph down) and 200 when it never could (this lead id
 *    is not ours, the form collected nothing). Answering 4XX to something a
 *    human can fix throws away a real customer to make a graph look tidy.
 */
const ctx = $('Verify Or Refuse').item.json || {};
/* event_id exists only because Record Lead Event created the row. Reading it
   off the gate — where it does not exist — is the mistake hop three's header
   already warns about; the same trap is one node earlier here. */
const recorded = $('Record Lead Event').item.json || {};

const pageId = String(ctx.page_id || '');
const leadgenId = String(ctx.leadgen_id || '');
const eventId = recorded.event_id ? String(recorded.event_id) : '';

const SUPABASE_URL = String($env.SUPABASE_URL || '').replace(/\/+$/, '');
const SERVICE_KEY  = String($env.SUPABASE_SERVICE_ROLE_KEY || $env.SUPABASE_KEY || '');
/* The vault kind registered in public.lead_ingest_secret_kind (FK). The
   dealer connect flow must store the Page token under exactly this kind. */
const PAGE_TOKEN_KIND = 'meta_page_access_token';
const recordedTenant = recorded.tenant_id ? String(recorded.tenant_id) : '';

/* Pinned, and validated rather than interpolated: a stray value here becomes a
   path segment on graph.facebook.com. v25.0 is what GO-LIVE.md measured. */
const GRAPH_VERSION =
  /^v\d+\.\d+$/.test(String($env.META_GRAPH_VERSION || '').trim())
    ? String($env.META_GRAPH_VERSION).trim() : 'v25.0';

/* Exactly the fields hop three allowlists, and not one more. Asking for less
   than hop three reads is a silently empty column; asking for more is data we
   have no stated purpose for holding about a person. */
const FIELDS = 'id,created_time,field_data,platform,form_id,ad_id,ad_name,' +
               'adset_id,adset_name,campaign_id,campaign_name,is_organic';

/* Never copied out of Graph's answer into an item, however Meta labels it. The
   database constraint and hop three's allowlist both cover the row that gets
   written; this covers the n8n execution record, which nothing else does. */
const NEVER_COPY = new Set([
  'access_token', 'app_secret', 'client_secret', 'api_key', 'apikey',
  'authorization', 'appsecret_proof', 'refresh_token', 'secret',
]);

const http = (typeof $helpers !== 'undefined' && $helpers && $helpers.httpRequest)
  ? $helpers.httpRequest.bind($helpers)
  : null;

let token = '';
let token_source = null;
let resolved_tenant_id = null, resolved_endpoint_id = null, resolved_source_key = null;

/* Everything the workflow needs to answer Meta and to leave a readable trace,
   with not one field that could carry a credential. `retryable` decides the
   status; `phase_remains` is the honest statement of what the row still is. */
const stop = (code, why, retryable, extra) => [{ json: Object.assign({
  verdict: 'NOT_FETCHED',
  reason_code: code,
  why,
  respond_status: retryable ? 500 : 200,
  respond_text: retryable ? code : 'ok',
  retryable: !!retryable,
  hydration_blocked: true,
  phase_remains: 'RECEIVED',
  event_id: eventId || null,
  page_id: pageId || null,
  leadgen_id: leadgenId || null,
  graph_version: GRAPH_VERSION,
  token_source,
  tenant_id: resolved_tenant_id,
  endpoint_id: resolved_endpoint_id,
  source_key: resolved_source_key,
}, extra || {}) }];

/* One place that talks to the database, so there is one place that can fail.
   Returns null on any failure rather than throwing: a vault that is unreachable
   must end in a refusal we can read, not an n8n exception with a stack trace
   that a dealership is then shown as "an error occurred". */
async function rpc(fn, body) {
  if (!http || !SUPABASE_URL || !SERVICE_KEY) return null;
  try {
    const res = await http({
      method: 'POST',
      url: SUPABASE_URL + '/rest/v1/rpc/' + fn,
      headers: { apikey: SERVICE_KEY, Authorization: 'Bearer ' + SERVICE_KEY,
                 'Content-Type': 'application/json' },
      body: body, json: true, timeout: 8000,
    });
    if (Array.isArray(res)) return res.length ? res[0] : null;
    return res || null;
  } catch (e) { return null; }
}

/* ---- Nothing can be fetched without the two ids and the row ---------------- */
if (!leadgenId) {
  return stop('NO_LEADGEN_ID_TO_FETCH',
    'Hop one accepted the delivery but carried no leadgen_id, so there is no ' +
    'lead to fetch. Nothing was written and nothing can be.', false);
}
if (!eventId) {
  /* Retryable on purpose: this means door one did not return an event_id, so
     there is no RECEIVED row to hydrate. A redelivery re-runs the whole chain
     and is deduplicated by nexus_record_lead_event, so a retry is safe and is
     the lead's only remaining chance. */
  return stop('NO_EVENT_ID_FROM_RECORD',
    'Record Lead Event returned no event_id, so there is no RECEIVED row to ' +
    'hydrate. Fetching the customer now would produce data with nowhere to go.',
    true);
}

/* ---- Which dealership's token, and only then the fetch -------------------- */
if (pageId) {
  const got = await rpc('nexus_lead_ingest_secret_reveal', {
    p_provider: 'meta',
    p_identity_kind: 'facebook_page_id',
    p_identity_value: pageId,
    p_kind: PAGE_TOKEN_KIND,
    p_reason: 'leadgen hydrate',
  });
  /* Named fields only. `got` is never spread, never logged and never returned:
     one of its columns is the token. */
  if (got && got.secret) {
    token = String(got.secret);
    token_source = 'vault_per_dealer';
    resolved_tenant_id = got.tenant_id || null;
    resolved_endpoint_id = got.endpoint_id || null;
    resolved_source_key = got.source_key || null;
  }
}

if (!token) {
  return stop('NO_PAGE_TOKEN_FOR_THIS_PAGE',
    (pageId
      ? ('No active ' + PAGE_TOKEN_KIND + ' is installed for Facebook Page ' + pageId +
         ' (Page not registered, endpoint or dealership not active, token not ' +
         'installed, or the vault was unreachable)')
      : 'This delivery named no page_id, so no dealership could be identified') +
    '. There is no box-wide fallback and there must not be. The dealership ' +
    'reconnects its Page, which stores the token with nexus_lead_ingest_secret_put.',
    true,
    { vault_reachable: !!(http && SUPABASE_URL && SERVICE_KEY) });
}

/* ---- Rule 2b: the token's dealership is the row's dealership ------------- */
if (!recordedTenant || !resolved_tenant_id ||
    String(resolved_tenant_id) !== recordedTenant) {
  const tokenTenant = resolved_tenant_id;
  token = '';
  return stop('PAGE_TOKEN_TENANT_MISMATCH',
    'The Page token the vault returned belongs to a different dealership than ' +
    'the one Record Lead Event wrote this row for (or one side named no ' +
    'dealership). Fetching would read one dealership\'s lead with another ' +
    'dealership\'s credential, or file it under the wrong one. Refusing. Fix ' +
    'the lead_ingest_provider_identity rows for this Page.', true,
    { recorded_tenant_id: recordedTenant || null, token_tenant_id: tokenTenant || null });
}

/* ---- The one call that turns an id into a person -------------------------- */
let status = null, body = null, reached = false;
try {
  const res = await http({
    method: 'GET',
    url: 'https://graph.facebook.com/' + GRAPH_VERSION + '/' +
         encodeURIComponent(leadgenId),
    qs: { fields: FIELDS },
    /* Header, not query string. See rule 1 in the header of this file. */
    headers: { Authorization: 'Bearer ' + token, Accept: 'application/json' },
    json: true,
    timeout: 15000,
    returnFullResponse: true,
  });
  reached = true;
  status = (res && typeof res.statusCode === 'number') ? res.statusCode : 200;
  body = (res && res.body !== undefined) ? res.body : res;
} catch (e) {
  /* e.message is NOT read. n8n puts the request line into it and Graph puts its
     own echo into the body; between them a token or a customer could ride out
     of here inside what looks like a diagnostic. Only the structured response
     is salvaged. */
  const r = (e && (e.response || (e.cause && e.cause.response))) || null;
  if (r) {
    reached = true;
    status = r.statusCode || r.status || null;
    body = (r.body !== undefined) ? r.body : r.data;
  }
}

if (!reached) {
  return stop('GRAPH_UNREACHABLE',
    'The call to graph.facebook.com did not complete at all — DNS, TLS, egress ' +
    'or timeout. No answer was received, so nothing is known about this lead ' +
    'either way.', true);
}

if (typeof body === 'string') {
  try { body = JSON.parse(body); } catch (e) { body = {}; }
}
if (!body || typeof body !== 'object' || Array.isArray(body)) body = {};

/* ---- Graph said no ------------------------------------------------------- */
if ((typeof status === 'number' && status >= 400) || body.error) {
  const err = (body.error && typeof body.error === 'object') ? body.error : {};
  const code = (err.code === undefined || err.code === null) ? null : Number(err.code);
  const subcode = (err.error_subcode === undefined || err.error_subcode === null)
    ? null : Number(err.error_subcode);
  const type = err.type ? String(err.type) : null;

  /* Our sentences, from the code. Never Meta's, which echoes the request. */
  let reason, why, retryable = true;
  if (code === 190) {
    reason = 'GRAPH_TOKEN_REJECTED';
    why = 'Meta rejected the access token itself (code 190): it is expired, ' +
          'revoked, or was issued by a different Meta app than the one that ' +
          'owns this Page. A short-lived Page token dies in hours and a ' +
          'long-lived one in about two months, which is why the answer is a ' +
          'System User token. Re-issue it and reinstall it with ' +
          'nexus_lead_ingest_secret_put — the leads that arrive meanwhile stop ' +
          'at RECEIVED.';
  } else if (code === 10) {
    reason = 'GRAPH_LEADS_RETRIEVAL_PERMISSION_MISSING';
    why = 'Meta refused the permission (code 10): this token may not read lead ' +
          'data. The token is missing the leads_retrieval scope, or the app is ' +
          'in Development mode for this Page. This is a property of the TOKEN, ' +
          'not of the Page grant — check the scopes on the System User token ' +
          'before touching Lead Access Manager.';
  } else if (code === 200) {
    reason = 'GRAPH_LEAD_ACCESS_NOT_GRANTED';
    why = 'Meta refused the permission (code 200): the token is valid and ' +
          'carries the scope, but this System User has not been granted Lead ' +
          'Access on the Page. Business Settings → Integrations → Lead Access ' +
          'Manager → this Page → add the System User (and the app). THIS IS ' +
          'THE FAILURE THAT LOOKS LIKE SUCCESS: the webhook arrives, we answer ' +
          'Meta 200, the dealership sees a connected source, and no customer ' +
          'ever appears.';
  } else if (code === 4 || code === 17 || code === 32 || code === 613) {
    reason = 'GRAPH_RATE_LIMITED';
    why = 'Meta rate-limited this app or this Page (code ' + code + '). The ' +
          'lead still exists on Meta; the fetch must be repeated later.';
  } else if (code === 1 || code === 2) {
    reason = 'GRAPH_TRANSIENT';
    why = 'Meta returned an unknown or temporary server error (code ' + code +
          '). Nothing here is misconfigured as far as this answer shows.';
  } else if (code === 100) {
    reason = 'GRAPH_LEAD_NOT_READABLE';
    why = 'Meta could not read this object as a lead (code 100). Either the ' +
          'leadgen_id does not name a lead this app can see, or the field list ' +
          'was rejected. A retry of the same request returns the same answer.';
    retryable = false;
  } else if (code === 803) {
    reason = 'GRAPH_LEAD_NOT_VISIBLE';
    why = 'Meta says the object is not visible to this token (code 803). It is ' +
          'most often a lead belonging to a Page this token does not administer.';
    retryable = false;
  } else {
    reason = 'GRAPH_ERROR_UNCLASSIFIED';
    why = 'Meta refused the fetch with an error this node does not classify. ' +
          'The code and subcode are carried below; the message is deliberately ' +
          'not, because Meta echoes the request into it and the request carried ' +
          'a token. Read the full message in the Graph API Explorer, not here.';
  }

  return stop(reason, why, retryable, {
    graph_status: status,
    graph_error_code: code,
    graph_error_subcode: subcode,
    graph_error_type: type,
  });
}

/* ---- Graph said yes, and it has to be the lead we asked for --------------- */
const returnedId = String(body.id || '');
if (returnedId !== leadgenId) {
  /* Not paranoia about Meta: this is what a mis-paired n8n item looks like when
     two leads arrive in one delivery. Hydrating here would write one customer's
     details onto another customer's event row, permanently, and the dealership
     would have no way to know. */
  return stop('GRAPH_LEAD_ID_MISMATCH',
    'Graph answered 200 for a different lead than the one requested — asked ' +
    'for ' + leadgenId + ', got ' + (returnedId || '(no id)') + '. Hydrating ' +
    'this row would attach one customer\'s answers to another customer\'s ' +
    'event. Refusing.', false,
    { graph_status: status, graph_returned_id: returnedId || null });
}

if (!Array.isArray(body.field_data) || body.field_data.length === 0) {
  return stop('GRAPH_LEAD_HAS_NO_FIELD_DATA',
    'Graph returned the lead but with no field_data, so there are no answers ' +
    'and therefore no customer. hop three would produce a normalized shape the ' +
    'promoter refuses anyway; it is said here, where the cause is visible.',
    false, { graph_status: status });
}

/* hop three reads `$input.first().json` as the Graph response itself, so the
   response IS the item and our own fields ride alongside it. Credential-named
   top-level keys are dropped first: hop three allowlists what reaches the
   database, but nothing else protects the execution record. */
const lead = {};
for (const [k, v] of Object.entries(body)) {
  if (NEVER_COPY.has(String(k).toLowerCase())) continue;
  lead[k] = v;
}

return [{ json: Object.assign(lead, {
  verdict: 'FETCHED',
  reason_code: 'LEAD_FETCHED',
  respond_status: 200,
  respond_text: 'ok',
  retryable: false,
  hydration_blocked: false,
  event_id: eventId,
  page_id: pageId || null,
  leadgen_id: leadgenId,
  graph_status: status,
  graph_version: GRAPH_VERSION,
  /* Always 'vault_per_dealer': there is no other source. */
  token_source,
  tenant_id: resolved_tenant_id,
  endpoint_id: resolved_endpoint_id,
  source_key: resolved_source_key,
}) }];

/* The exact body of the "Normalize And Redact" Code node in the n8n workflow
 * "Meta Lead Ads - Inbound Receiver".
 *
 * Input: the Graph API response for GET /v<v>/<leadgen_id>, which is the ONLY
 * place the customer's details exist — the webhook carried none.
 *
 * Output: `hydrated_payload` (what Meta said, cleaned) and `normalized` (the
 * five fields the promoter needs). Both go into a row a dealership can read, so
 * neither may carry a credential.
 *
 * THREE THINGS THIS NODE IS RESPONSIBLE FOR, AND WHY EACH IS HERE AND NOT LATER
 *
 * 1. AN ALLOWLIST FIRST, AND A FILTER ONLY WHERE AN ALLOWLIST CANNOT REACH.
 *    `lead_event_payload_carries_no_shared_secret` refuses a row whose
 *    payload_raw OR hydrated_payload contains a key named access_token,
 *    app_secret, client_secret, api_key, authorization or google_key. That
 *    constraint is the backstop, not the plan: relying on it means the first
 *    leaked token fails the whole delivery and the lead is lost.
 *
 *    So `hydrated_payload` is assembled field by field from a NAMED LIST. It is
 *    not Meta's response with the bad parts taken out; it is our own object with
 *    only the parts we asked for put in. Nothing Meta adds to that endpoint next
 *    year can arrive here by default — including a credential. This was written
 *    the other way round first, as a scrub over the whole response, and the test
 *    that proved the scrub worked also proved the scrub was never reached.
 *
 *    ONE branch is copied wholesale and therefore cannot be allowlisted:
 *    `field_data`, the customer's own answers, which we must not edit. That is
 *    the door `scrub()` guards. It drops keys with credential names and values
 *    shaped like a Meta token (EAA… past 100 characters). It does NOT do general
 *    "looks secret-ish" filtering on free text — a customer's message is not
 *    ours to mangle, and a redacted enquiry is a lost enquiry.
 *
 * 2. ATTRIBUTION AS AN ADDITIVE FACT, NEVER AS THE IDENTITY.
 *    Meta delivers Instagram lead ads on the connected Facebook Page's leadgen
 *    subscription, and the webhook has no platform field — so at RECEIVED time
 *    nobody can know which it was. The Graph response often carries `platform`.
 *    It is recorded in hydrated_payload as `ad_platform`, and it MUST NOT be
 *    turned into source_key: lead_event_identity_key is
 *    UNIQUE (tenant_id, source_key, external_event_id), so changing source_key
 *    would make Meta's redelivery of the same leadgen_id look new and hand the
 *    dealership two leads for one customer. Attribution rides alongside the
 *    identity; it is never part of it.
 *
 *    When `platform` is absent, ad_platform is null and ad_platform_confidence
 *    is 'UNKNOWN'. It is not guessed from the ad name.
 *
 * 3. A NORMALIZED SHAPE THE PROMOTER WILL ACCEPT, OR AN HONEST REFUSAL.
 *    nexus_lead_normalized_defect() requires a full name and at least one of
 *    email or phone. If Meta's form did not ask for enough to reach the person,
 *    that is a real fact about the form and it is reported as such rather than
 *    padded with a placeholder.
 */
const src = $input.first().json || {};
/* Two different upstreams, on purpose. The identifiers Meta signed come from the
   gate; the event_id exists only because Record Lead Event created the row. An
   earlier draft read event_id off the gate, where it does not exist, and would
   have hydrated `undefined` on the first real lead. */
const ctx = $('Verify Or Refuse').item.json;
const recorded = $('Record Lead Event').item.json;
const eventId = recorded && recorded.event_id;

/* Meta user access tokens start EAA and run well past 100 characters. Short
   strings are never matched, so an ordinary answer cannot be eaten by this. */
const TOKEN_SHAPED = /^EAA[A-Za-z0-9_-]{100,}$/;
const SECRET_KEYS = new Set([
  'access_token', 'app_secret', 'client_secret', 'api_key', 'apikey',
  'authorization', 'google_key', 'appsecret_proof', 'refresh_token',
  'client_id_secret', 'secret',
]);

/* The exact-match rule. See the long note further down: what trips
   lead_event_payload_carries_no_shared_secret is a string -- key or value, at
   any depth -- that is exactly one of the six words. Substrings never trip it.

   It is applied to VALUES only, and that is not an oversight. Every one of the
   six words is already in SECRET_KEYS above, so a KEY equal to one of them is
   dropped as a credential before any repair could run: a rename branch for keys
   would be unreachable code pretending to be a defence. And in both providers
   the question LABEL travels as a value -- Meta's field_data[].name, Google's
   user_column_data[].column_name -- so the value path is the one that fires. */
const BARE_CONSTRAINT_WORD =
  /^(google_key|app_secret|client_secret|access_token|api_key|authorization)$/i;
const CONSTRAINT_NOTE =
  ' (stored with this note because the bare word is refused by a database constraint; ' +
  'the customer wrote it exactly as it appears before this bracket)';

let strippedKeys = 0, strippedValues = 0, annotatedValues = 0;
function scrub(v, depth) {
  if (depth > 12) return null;
  if (Array.isArray(v)) return v.map(x => scrub(x, depth + 1));
  if (v && typeof v === 'object') {
    const out = {};
    for (const [k, val] of Object.entries(v)) {
      if (SECRET_KEYS.has(String(k).toLowerCase())) { strippedKeys++; continue; }
      out[k] = scrub(val, depth + 1);
    }
    return out;
  }
  if (typeof v === 'string' && TOKEN_SHAPED.test(v)) { strippedValues++; return '[redacted]'; }
  /* A question LABEL or a customer's ANSWER that is exactly one of the six
     words. Nothing is deleted and nothing is rewritten: the word still starts
     the string, and the note says why the rest is there. `normalized` -- what a
     salesperson actually reads -- is a different column the constraint does not
     cover and is left alone entirely. */
  if (typeof v === 'string' && BARE_CONSTRAINT_WORD.test(v)) {
    annotatedValues++;
    return v + CONSTRAINT_NOTE;
  }
  return v;
}

/* ---- field_data → a flat map ---------------------------------------------- */
const fields = {};
for (const f of (src.field_data || [])) {
  const name = String((f && f.name) || '').trim().toLowerCase();
  if (!name) continue;
  const vals = Array.isArray(f.values) ? f.values.map(x => String(x == null ? '' : x).trim()) : [];
  fields[name] = vals.filter(Boolean).join(' ').trim();
}

const pick = (...names) => { for (const n of names) if (fields[n]) return fields[n]; return ''; };

let full_name = pick('full_name', 'name');
if (!full_name) {
  full_name = [pick('first_name'), pick('last_name')].filter(Boolean).join(' ').trim();
}
const email = pick('email').toLowerCase();

/* E.164 or nothing. Pasting a country code onto a number that was never local
   is how you message a stranger, so an unrecognised shape is reported as
   unparseable rather than repaired. Meta normally returns a leading +. */
function toE164(rawPhone) {
  const s = String(rawPhone || '').replace(/[^\d+]/g, '');
  if (/^\+[1-9]\d{7,14}$/.test(s)) return s;
  const d = s.replace(/\D/g, '');
  if (/^00[1-9]\d{7,14}$/.test(d)) return '+' + d.slice(2);
  if (/^971\d{9}$/.test(d)) return '+' + d;      // UAE, already prefixed
  if (/^0?5\d{8}$/.test(d)) return '+971' + d.replace(/^0/, '');  // UAE mobile as 05x
  if (/^91[6-9]\d{9}$/.test(d)) return '+' + d;  // India, already prefixed
  return null;
}
const phoneRaw = pick('phone_number', 'phone', 'mobile_number', 'mobile');
const phone_e164 = toE164(phoneRaw);

const vehicle = pick('vehicle_of_interest', 'vehicle', 'car_model', 'which_model_are_you_interested_in',
                     'model', 'what_are_you_looking_for');
/* Anything the form asked that is not one of the identity fields is kept as the
   customer's own words, so a dealership sees the answers it paid to collect. */
const KNOWN = new Set(['full_name', 'name', 'first_name', 'last_name', 'email',
                       'phone_number', 'phone', 'mobile_number', 'mobile']);
const extras = Object.entries(fields)
  .filter(([k, v]) => !KNOWN.has(k) && v)
  .map(([k, v]) => k.replace(/_/g, ' ') + ': ' + v);

const normalized = { full_name };
if (phone_e164) normalized.phone_e164 = phone_e164;
if (email) normalized.email = email;
if (vehicle) normalized.vehicle_of_interest = vehicle;
if (extras.length) normalized.message = extras.join(' | ');

/* ---- what the promoter will refuse, decided here rather than by a 500 ------ */
let defect = null;
if (!full_name) defect = 'NORMALIZED_FULL_NAME_REQUIRED';
else if (!phone_e164 && !email) defect = 'NORMALIZED_NEEDS_EMAIL_OR_PHONE';

const platform = String(src.platform || '').toLowerCase();
const ad_platform = (platform === 'instagram' || platform === 'facebook') ? platform : null;

/* ---- field_data, and a constraint that can destroy a real lead ------------
   `lead_event_payload_carries_no_shared_secret` is a TEXT match over the whole
   serialised JSON:

       hydrated_payload::text !~* '"(google_key|app_secret|client_secret|
                                    access_token|api_key|authorization)"'

   It does not distinguish a key from a value, and a failed insert here is a
   customer who filled in the form and was thrown away. Same shape as answering
   Google a 4XX.

   MEASURED against Postgres rather than reasoned about, because the regex needs
   a literal quote on both sides and JSON escaping decides whether there is one.
   Re-measured on 7 September 2026, and the second measurement CORRECTED THE
   FIRST:

     {"name":"api_key"}                        -> REFUSES   (a question label)
     {"column_id":"API_KEY"}                   -> REFUSES   (case-insensitive)
     {"name":"my_api_key"}                     -> accepted  (a substring never trips it)
     {"values":["authorization"]}              -> REFUSES   (an ANSWER, on its own)
     {"values":["my api_key is broken"]}       -> accepted
     an answer containing "api_key" IN QUOTES  -> accepted   (jsonb escapes them)
     {"values":["api_key "]}                   -> accepted  (a trailing space clears it)
     {"a":{"b":{"c":{"d":"access_token"}}}}    -> REFUSES   (depth is irrelevant)

   The fourth line is a defect this file shipped with. The first pass read only
   question LABELS, and read them with a SUBSTRING regex -- so a real customer
   whose whole answer was "authorization" would have failed the insert and been
   thrown away, while a harmless label like "my_api_key", which never trips the
   constraint at all, was renamed for nothing. Wrong in both directions, out of
   one wrong rule: I had measured an embedded word and generalised it to every
   word.

   What actually trips it is a string -- key or value, any depth -- that is
   EXACTLY one of the six words. So the rule is exact-match and it now lives
   inside scrub(), which already walks this branch. It runs on VALUES only: see
   the note beside BARE_CONSTRAINT_WORD for why a key needs no repair. The
   string keeps the customer's word and gains a stated note, because one
   trailing character is all the constraint needs and deleting a customer's
   answer to satisfy a regex is not a repair. `normalized` -- the text a
   salesperson reads -- is a different column the constraint does not cover and
   is left exactly as the customer wrote it. */
const scrubbedFieldData = scrub(src.field_data || [], 0) || [];
const renamedQuestions = 0;  /* see above: the key path is unreachable */

const hydrated_payload = {
  provider: 'meta',
  graph_lead_id: String(src.id || ''),
  created_time: src.created_time || null,
  form_id: String(src.form_id || ctx.form_id || ''),
  ad_id: String(src.ad_id || ctx.ad_id || ''),
  ad_name: src.ad_name || null,
  adset_id: src.adset_id || null,
  adset_name: src.adset_name || null,
  campaign_id: src.campaign_id || null,
  campaign_name: src.campaign_name || null,
  is_organic: typeof src.is_organic === 'boolean' ? src.is_organic : null,
  /* Attribution, additive. See the header: this never becomes source_key. */
  ad_platform,
  ad_platform_confidence: ad_platform ? 'PROVIDER_REPORTED' : 'UNKNOWN',
  ad_platform_evidence: ad_platform
    ? 'Meta returned platform="' + platform + '" on the lead node.'
    : 'Meta returned no platform on the lead node. The webhook cannot say either: '
      + 'Instagram lead ads arrive on the Facebook Page leadgen subscription. '
      + 'Not guessed from the ad or campaign name.',
  /* The one branch not allowlisted: the customer's own answers, copied
     wholesale because we must not edit them. scrub() guards exactly this. */
  field_data: scrubbedFieldData,
  phone_unparseable: phone_e164 ? null : (phoneRaw || null),
  constraint_safety: { renamed_questions: renamedQuestions,
                       annotated_answers: annotatedValues },
};

return [{ json: {
  event_id: eventId,
  leadgen_id: ctx.leadgen_id,
  hydrated_payload,
  /* Untouched on purpose: this is what a salesperson reads. */
  normalized,
  normalized_defect: defect,
  can_promote: defect === null,
  ad_platform,
  /* Counted over field_data only. Zero is the normal, healthy answer:
     the rest of hydrated_payload is an allowlist and never needed one. */
  renamed_questions: renamedQuestions,
  /* An answer that was exactly a credential word. Zero is the normal answer;
     a non-zero count is a lead that WOULD have been destroyed before today. */
  annotated_answers: annotatedValues,
  field_data_stripped_keys: strippedKeys,
  field_data_stripped_token_shaped_values: strippedValues,
} }];
